class Common {
public:
    int data;
    Common(int d) : data(d) {}
};

class Left : virtual public Common {
public: Left() : Common(1) {}
};

class Right : virtual public Common {
public: Right() : Common(2) {}
};

// The most derived class (Derived) is responsible
// for constructing the virtual base (Common).
class Derived : public Left, public Right {
public:
    Derived() : Common(3) {} // Initializes the single Common instance
};

// Derived obj; // obj.data == 3
// sizeof(Derived) includes Common only once.
